// 표준 API 조합으로 새로 작성한 검사 함수
/**
 * @method
 * @name scwin.emailCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name scwin.mpd_files_selectCallback
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name scwin.checkRegData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkRegData = function () {
    /* sdd-asis-lifecycle:begin checkRegData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const vl = dma_hiddenStore.get("regType");
    if (vl !== '') {
        const tObj = $('input[name=std_cd_apct_tp_cd][value="' + vl + '"]');
        if (tObj.length > 0) {
            $(tObj)[0].checked = true;
        }
    }
    const email = dma_hiddenStore.get("ipt_regEmail");
    if (email !== '') {
        const emails = email.split("@");
        if (emails.length > 0) {
            $c.util.getComponent('ipt_email01').setValue(emails[0]);
        }
        if (emails.length > 1) {
            $c.util.getComponent('ipt_email02').setValue(emails[1]);
        }
    }
    const tel = dma_hiddenStore.get("ipt_regTel");
    if (tel !== '') {
        const tels = tel.split("-");
        if (tels.length > 0) {
            $c.util.getComponent('ipt_ph01').setValue(tels[0]);
        }
        if (tels.length > 1) {
            $c.util.getComponent('ipt_ph02').setValue(tels[1]);
        }
        if (tels.length > 2) {
            $c.util.getComponent('ipt_ph03').setValue(tels[2]);
        }
    }
    const fax = dma_hiddenStore.get("ipt_regFax");
    if (fax !== '') {
        const faxs = fax.split("-");
        if (faxs.length > 0) {
            $c.util.getComponent('ipt_fax01').setValue(faxs[0]);
        }
        if (faxs.length > 1) {
            $c.util.getComponent('ipt_fax02').setValue(faxs[1]);
        }
        if (faxs.length > 2) {
            $c.util.getComponent('ipt_fax03').setValue(faxs[2]);
        }
    }
    const hpNo = $c.util.getComponent('ipt_encrypCellphoneNo').getValue();
    const hpNos = hpNo.split("-");
    if (hpNos.length > 0) {
        $c.util.getComponent('ipt_encrypCellphoneNo1').setValue(hpNos[0]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo2').setValue(hpNos[1]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo3').setValue(hpNos[2]);
    }
