/**
 * @method
 * @name scwin.Chk_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.Chk_form = async function () {
    /* sdd-asis-lifecycle:begin Chk_form — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const chkBl = await scwin.dataValidation();
    if (chkBl) {
        return;
    }
    $c.util.getComponent('ipt_isuAmt').setValue(($c.util.getComponent("ipt_isuAmt").getValue() || '').replace(/\,/g, ''));
    const telNo = $c.util.getComponent('ipt_ph01').getValue() + "-" + $c.util.getComponent('ipt_ph02').getValue() + "-" + $c.util.getComponent('ipt_ph03').getValue();
    const faxNo = $c.util.getComponent('ipt_fax01').getValue() + "-" + $c.util.getComponent('ipt_fax02').getValue() + "-" + $c.util.getComponent('ipt_fax03').getValue();
    const emailNo = $c.util.getComponent('ipt_email01').getValue() + '@' + $c.util.getComponent('ipt_email02').getValue();
    const encryp_cellphone_no = $c.util.getComponent('ipt_encrypCellphoneNo1').getValue() + "-" + $c.util.getComponent('ipt_encrypCellphoneNo2').getValue() + "-" + $c.util.getComponent('ipt_encrypCellphoneNo3').getValue();
    if (!$c.str.isEmail(emailNo)) {
        await $c.win.alert("이메일 주소 형식이 아닙니다.");
        $c.util.getComponent("ipt_email01").focus();
        return;
    }
    if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
        return;
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return;
    }
    $c.util.getComponent('ipt_encrypApctEmail').setValue(emailNo);
    $c.util.getComponent('ipt_apctTelNo').setValue(telNo);
    $c.util.getComponent('ipt_apctFaxNo').setValue(faxNo);
    $c.util.getComponent('ipt_encrypCellphoneNo').setValue(encryp_cellphone_no);
    if (await $c.win.confirm("수정하시겠습니까?")) {
        const fm = (document.JLDINF92600 || { elements: [] });
        fm.action = "/stdcd/mfInvest.do?method=investModifyProcess";
        fm.target = "_top";
        await scwin.tx_Chk_form();
    }
    /* sdd-asis-lifecycle:end */
};


